/// Supported QUIC versions in the same declaration order as
/// `picoquic_supported_versions[]`.
pub const SUPPORTED_VERSIONS: [Version; 13] = [
    Version::V1,
    Version::V2,
    Version::V2Draft,
    Version::PostIesg,
    Version::TwentyFirstInterop,
    Version::TwentiethInterop,
    Version::TwentiethPreInterop,
    Version::NineteenthInterop,
    Version::NineteenthBisInterop,
    Version::EighteenthInterop,
    Version::SeventeenthInterop,
    Version::InternalTest2,
    Version::InternalTest1,
];

fn fill_system_random(bytes: &mut [u8]) -> crate::Result<()> {
    std::fs::File::open("/dev/urandom")
        .and_then(|mut file| file.read_exact(bytes))
        .map_err(|_| crate::Error::Generic)
}

pub(crate) fn public_random(bytes: &mut [u8]) {
    let mut off = 0;
    while off < bytes.len() {
        let mut random = crate::public_random_64();
        for _ in 0..8 {
            if off >= bytes.len() {
                break;
            }
            bytes[off] = random as u8;
            random >>= 8;
            off += 1;
        }
    }
}

fn public_uniform_random(rnd_max: u64) -> u64 {
    if rnd_max == 0 {
        return 0;
    }
    let rnd_min = u64::MAX % rnd_max;
    loop {
        let rnd = crate::public_random_64();
        if rnd >= rnd_min {
            return rnd % rnd_max;
        }
    }
}

// ---------------------------------------------------------------------------
// Range / bitfield helper macros.

/// `IN_RANGE(v, min, max)` — true when `min ≤ v ≤ max`
/// under the C macro's bitfield assumption (`min & max == min`,
/// `min & bits == 0`, `max & bits == bits`).
#[inline]
pub const fn in_range(v: u64, min: u64, max: u64) -> bool {
    (v & !(min ^ max)) == min
}

/// `BITS_SET_IN_RANGE(v, min, max, bits)`.
#[inline]
pub const fn bits_set_in_range(v: u64, min: u64, max: u64, bits: u64) -> bool {
    (v & !(min ^ max ^ bits)) == (min ^ bits)
}

/// `BITS_CLEAR_IN_RANGE(v, min, max, bits)`.
#[inline]
pub const fn bits_clear_in_range(v: u64, min: u64, max: u64, bits: u64) -> bool {
    (v & !(min ^ max ^ bits)) == min
}

