        const V1_PREFIX: &str = "tls13 quic ";
        const V2_PREFIX: &str = "tls13 quicv2 ";
        const V1_KU: &str = "quic ku";
        const V2_KU: &str = "quicv2 ku";

        const UPGRADE_FROM_V1: &[Version] = &[Version::V1];

